             header=[T('Site', 'Site'), T('Alginate yield (t/t DM)', 'Rendement alginate (t/t MS)'), T('Alginate (t/yr)', 'Alginate (t/an)'), T('Increment (M€/yr)', 'Apport (M€/an)'), T('Break-even, packaging only (€/kg)', 'Seuil, emballage seul (€/kg)'), T('Break-even, with food grade (€/kg)', 'Seuil, avec alimentaire (€/kg)')],
